const now = DateTime.now().setZone('Europe/Berlin');
return [{
  json: {
    webUntisUrl: process.env.WEBUNTIS_URL,
    webUntisSchool: process.env.WEBUNTIS_SCHOOL,
    classId: Number(process.env.WEBUNTIS_CLASS_ID),
    start: now.startOf('week').minus({ weeks: 1 }).toISODate(),
    end: now.plus({ weeks: 8 }).endOf('week').toISODate(),
    radicaleCalendarUrl: process.env.RADICALE_CALENDAR_URL,
    courses: JSON.parse(process.env.WEBUNTIS_COURSES_JSON),
    dryRun: false,
  },
}];

const cfg = $('Konfiguration').first().json;
const response = $input.first().json;

if (!Array.isArray(response.days) || response.errors?.length) {
  throw new Error(`WebUntis lieferte keine gültigen Stundenplandaten: ${JSON.stringify(response.errors ?? response)}`);
}

const COURSES = cfg.courses;

// DTEND ist bei ganztägigen iCalendar-Terminen exklusiv.
const CALENDAR_BREAKS = [
  { start: '2026-08-03', end: '2026-09-15', title: 'Sommerferien' },
  { start: '2026-11-02', end: '2026-11-07', title: 'Allerheiligenferien' },
  { start: '2026-12-24', end: '2027-01-09', title: 'Weihnachtsferien' },
  { start: '2027-02-08', end: '2027-02-13', title: 'Frühjahrsferien' },
  { start: '2027-03-22', end: '2027-04-03', title: 'Osterferien' },
  { start: '2027-05-18', end: '2027-05-29', title: 'Pfingstferien' },
  { start: '2027-08-02', end: '2027-09-14', title: 'Sommerferien' },
  { start: '2026-10-03', end: '2026-10-04', title: 'Tag der Deutschen Einheit', type: 'Feiertag' },
  { start: '2026-11-01', end: '2026-11-02', title: 'Allerheiligen', type: 'Feiertag' },
  { start: '2026-11-18', end: '2026-11-19', title: 'Buß- und Bettag · schulfrei', type: 'Schulfrei' },
  { start: '2026-12-25', end: '2026-12-26', title: '1. Weihnachtsfeiertag', type: 'Feiertag' },
  { start: '2026-12-26', end: '2026-12-27', title: '2. Weihnachtsfeiertag', type: 'Feiertag' },
  { start: '2027-01-01', end: '2027-01-02', title: 'Neujahr', type: 'Feiertag' },
  { start: '2027-01-06', end: '2027-01-07', title: 'Heilige Drei Könige', type: 'Feiertag' },
  { start: '2027-03-26', end: '2027-03-27', title: 'Karfreitag', type: 'Feiertag' },
  { start: '2027-03-29', end: '2027-03-30', title: 'Ostermontag', type: 'Feiertag' },
  { start: '2027-05-01', end: '2027-05-02', title: 'Tag der Arbeit', type: 'Feiertag' },
  { start: '2027-05-06', end: '2027-05-07', title: 'Christi Himmelfahrt', type: 'Feiertag' },
  { start: '2027-05-17', end: '2027-05-18', title: 'Pfingstmontag', type: 'Feiertag' },
  { start: '2027-05-27', end: '2027-05-28', title: 'Fronleichnam', type: 'Feiertag' },
];

const normalize = value => String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase();
const nameOf = element => normalize(element?.shortName || element?.displayName || element?.longName);
const displayOf = element => element?.shortName || element?.displayName || element?.longName || '';
const longDisplayOf = element => element?.longName || element?.displayName || element?.shortName || '';
const valuesAt = (entry, key) => (entry[key] ?? []).map(pair => ({ current: pair?.current ?? null, removed: pair?.removed ?? null }));
const allNames = pairs => pairs.flatMap(pair => [nameOf(pair.current), nameOf(pair.removed)]).filter(Boolean);
const subjectMatches = (pairs, course) => allNames(pairs).some(name => course.aliases.some(alias => normalize(alias) === name));
const teacherIndex = (pairs, teacher) => pairs.findIndex(pair => nameOf(pair.current) === normalize(teacher) || nameOf(pair.removed) === normalize(teacher));
const weekday = isoDate => ['SO', 'MO', 'DI', 'MI', 'DO', 'FR', 'SA'][new Date(`${isoDate}T12:00:00`).getDay()];
const hhmm = isoDateTime => String(isoDateTime).slice(11, 16);
const slotKey = entry => `${weekday(entry.duration.start.slice(0, 10))} ${hhmm(entry.duration.start)}`;
const resolveRoom = (roomPairs, course) => {
  const currentRooms = roomPairs.map(pair => displayOf(pair.current)).filter(Boolean);
  // Wird ein Raum getauscht, behaelt das Paar den Vorgaenger in `removed`.
  // Ersetzt ein Paar genau den Stammraum dieses Kurses, ist dessen `current`
  // der neue eigene Raum. Das ist die einzige Stelle, an der der Feed Raum und
  // Kurs verknuepft: position1 und position3 sind getrennt sortierte Listen,
  // eine Zuordnung ueber den Index gibt es nicht.
  //
  // Ohne diesen Zweig fiel eine Raumaenderung durch alle Heuristiken: der
  // Stammraum steht dann nicht mehr in currentRooms, und nach Abzug der
  // peerRooms bleiben zwei Kandidaten uebrig statt einem. Ergebnis war room:''
  // und damit ein Termin voellig ohne LOCATION.
  const replacedPair = roomPairs.find(pair => course.room && normalize(displayOf(pair.removed)) === normalize(course.room));
  if (replacedPair && displayOf(replacedPair.current)) {
    return { room: displayOf(replacedPair.current), changed: true, ambiguous: false };
  }
  if (course.room && currentRooms.some(room => normalize(room) === normalize(course.room))) {
    return { room: course.room, changed: false, ambiguous: false };
  }
  if (currentRooms.length === 1) {
    return { room: currentRooms[0], changed: Boolean(course.room && normalize(currentRooms[0]) !== normalize(course.room)), ambiguous: false };
  }
  if (course.room && currentRooms.length > 1) {
    const otherBaselineRooms = course.peerRooms.filter(room => normalize(room) !== normalize(course.room));
    const unmatched = currentRooms.filter(room => !otherBaselineRooms.some(other => normalize(other) === normalize(room)));
    if (unmatched.length === 1) return { room: unmatched[0], changed: true, ambiguous: false };
  }
  return { room: '', changed: false, ambiguous: currentRooms.length > 1 };
};
const escapeIcs = value => String(value ?? '').replace(/\\/g, '\\\\').replace(/\r?\n/g, '\\n').replace(/,/g, '\\,').replace(/;/g, '\\;');
const fold = line => {
  const chunks = [];
  let rest = line;
  while (Buffer.byteLength(rest, 'utf8') > 73) {
    let cut = Math.min(70, rest.length);
    while (cut > 1 && Buffer.byteLength(rest.slice(0, cut), 'utf8') > 73) cut--;
    chunks.push(rest.slice(0, cut));
    rest = rest.slice(cut);
  }
  chunks.push(rest);
  return chunks.join('\r\n ');
};
const fnv1a = value => {
  let hash = 0x811c9dc5;
  for (let i = 0; i < value.length; i++) {
    hash ^= value.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
};
const toIcsTime = iso => `${iso.slice(0, 4)}${iso.slice(5, 7)}${iso.slice(8, 10)}T${iso.slice(11, 13)}${iso.slice(14, 16)}00`;
const toIcsDate = iso => iso.replaceAll('-', '');
const isBlockedSchoolDate = date => CALENDAR_BREAKS.some(period => date >= period.start && date < period.end);

const state = $getWorkflowStaticData('global');
state.hashByHref ??= {};
const desired = new Map();
const warnings = [];
let ignored = 0;

for (const day of response.days) {
  for (const entry of [...(day.gridEntries ?? []), ...(day.dayEntries ?? [])]) {
    if (!entry.duration?.start || !entry.duration?.end) { ignored++; continue; }
    if (isBlockedSchoolDate(entry.duration.start.slice(0, 10))) { ignored++; continue; }
    const teachers = valuesAt(entry, 'position1');
    const subjects = valuesAt(entry, 'position2');
    const rooms = valuesAt(entry, 'position3');
    const slot = slotKey(entry);
    let course = COURSES.find(candidate => subjectMatches(subjects, candidate) && teacherIndex(teachers, candidate.teacher) >= 0);
    let index = course ? teacherIndex(teachers, course.teacher) : -1;

    if (!course && normalize(entry.status) !== 'REGULAR') {
      const slotCandidates = COURSES.filter(candidate => candidate.slots.includes(slot) && subjectMatches(subjects, candidate));
      if (slotCandidates.length === 1 && teachers.length === 1) {
        course = slotCandidates[0];
        index = 0;
      }
    }
    if (!course) { ignored++; continue; }

    const teacherPair = teachers[index] ?? null;
    const actualTeacher = displayOf(teacherPair?.current);
    const originalTeacher = displayOf(teacherPair?.removed) || (actualTeacher ? course.teacher : '');
    const roomResult = resolveRoom(rooms, course);
    const room = roomResult.room;
    const currentSubjects = subjects.map(pair => displayOf(pair.current)).filter(Boolean);
    const removedSubjects = subjects.map(pair => displayOf(pair.removed)).filter(Boolean);
    const currentSubjectIsOwn = subjects.some(pair => pair.current && course.aliases.some(alias => normalize(alias) === nameOf(pair.current)));
    const actualSubject = currentSubjectIsOwn ? course.subject : longDisplayOf(subjects.find(pair => pair.current)?.current) || course.subject;
    const isCancelled = normalize(entry.status) === 'CANCELLED' || (!teacherPair?.current && teacherPair?.removed);
    if (isCancelled) continue;

    if (roomResult.ambiguous) warnings.push(`${entry.duration.start} ${course.subject}: Raum nicht eindeutig.`);
    const teacherLabel = actualTeacher || course.teacher;
    const teacherChanged = Boolean(teacherPair?.removed) && nameOf(teacherPair.removed) !== nameOf(teacherPair.current);
    const roomChanged = roomResult.changed;
    const subjectChanged = subjects.some(pair => pair.removed && nameOf(pair.removed) !== nameOf(pair.current));
    const changed = teacherChanged || roomChanged || subjectChanged;
    const titleSubject = actualSubject;
    const summary = `${titleSubject} · ${teacherLabel}${changed ? ' (Änderung)' : ''}`;
    const sourceIds = Array.isArray(entry.ids) ? entry.ids.join('-') : String(entry.id ?? '');
    const identity = `${course.id}|${entry.duration.start}|${sourceIds}`;
    const href = `webuntis-n8n-${fnv1a(identity)}.ics`;
    const uid = `webuntis-${fnv1a(identity)}@n8n.local`;
    const description = [
      'Automatisch aus dem öffentlichen Q13-Stundenplan von WebUntis synchronisiert.',
      `Persönlicher Kurs: ${course.subject} · ${course.teacher === 'RO' ? 'RÖ' : course.teacher}`,
      changed ? `Aktuell: ${titleSubject} · ${teacherLabel}` : '',
      originalTeacher && normalize(originalTeacher) !== normalize(teacherLabel) ? `Ursprüngliche Lehrkraft: ${originalTeacher}` : '',
      roomChanged && course.room ? `Stammraum laut allgemeinem Plan: ${course.room}` : '',
      removedSubjects.length ? `Ursprüngliches Fach: ${removedSubjects.join(', ')}` : '',
      changed && entry.substitutionText ? `Vertretung: ${entry.substitutionText}` : '',
      entry.lessonText ? `Hinweis: ${entry.lessonText}` : '',
      entry.lessonInfo ? `Info: ${entry.lessonInfo}` : '',
    ].filter(Boolean).join('\n');
    const lines = [
      'BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//n8n//WebUntis Radicale Sync//DE', 'CALSCALE:GREGORIAN',
      'BEGIN:VTIMEZONE', 'TZID:Europe/Berlin',
      'BEGIN:STANDARD', 'DTSTART:19961027T030000', 'RRULE:FREQ=YEARLY;BYMONTH=10;BYDAY=-1SU',
      'TZNAME:CET', 'TZOFFSETFROM:+0200', 'TZOFFSETTO:+0100', 'END:STANDARD',
      'BEGIN:DAYLIGHT', 'DTSTART:19810329T020000', 'RRULE:FREQ=YEARLY;BYMONTH=3;BYDAY=-1SU',
      'TZNAME:CEST', 'TZOFFSETFROM:+0100', 'TZOFFSETTO:+0200', 'END:DAYLIGHT', 'END:VTIMEZONE',
      'BEGIN:VEVENT', `UID:${uid}`,
      `DTSTART;TZID=Europe/Berlin:${toIcsTime(entry.duration.start)}`,
      `DTEND;TZID=Europe/Berlin:${toIcsTime(entry.duration.end)}`,
      'DTSTAMP:20260915T000000Z', `SUMMARY:${escapeIcs(summary)}`,
      room ? `LOCATION:${escapeIcs(room)}` : '', `DESCRIPTION:${escapeIcs(description)}`,
      `X-N8N-WEBUNTIS-ENTRY-IDS:${escapeIcs(sourceIds)}`, 'END:VEVENT', 'END:VCALENDAR',
    ].filter(Boolean).map(fold);
    const body = `${lines.join('\r\n')}\r\n`;
    desired.set(href, { href, body, hash: fnv1a(body), date: entry.duration.start.slice(0, 10), course: course.id });
  }
}

const matchedLessons = desired.size;
for (const period of CALENDAR_BREAKS) {
  const type = period.type || 'Ferien';
  const identity = `calendar-break|${period.start}|${period.end}|${period.title}`;
  const href = `webuntis-n8n-break-${fnv1a(identity)}.ics`;
  const uid = `webuntis-break-${fnv1a(identity)}@n8n.local`;
  const lines = [
    'BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//n8n//WebUntis Radicale Sync//DE', 'CALSCALE:GREGORIAN',
    'BEGIN:VEVENT', `UID:${uid}`, `DTSTART;VALUE=DATE:${toIcsDate(period.start)}`,
    `DTEND;VALUE=DATE:${toIcsDate(period.end)}`, 'DTSTAMP:20260915T000000Z',
    `SUMMARY:${escapeIcs(`${type} · ${period.title}`)}`,
    `DESCRIPTION:${escapeIcs('Schulfreier Zeitraum. Der WebUntis-Workflow trägt währenddessen keinen Unterricht ein.')}`,
    'TRANSP:TRANSPARENT', 'END:VEVENT', 'END:VCALENDAR',
  ].map(fold);
  const body = `${lines.join('\r\n')}\r\n`;
  desired.set(href, { href, body, hash: fnv1a(body), date: period.start, course: 'calendar-break' });
}

if (!desired.size) throw new Error('Kein persönlicher Kurs wurde erkannt. Abbruch ohne Löschungen.');
const feedDates = response.days.map(day => day.date).filter(Boolean).sort();
const feedMinDate = feedDates[0];
const feedMaxDate = feedDates[feedDates.length - 1];
const baseUrl = String(cfg.radicaleCalendarUrl).replace(/\/+$/, '') + '/';
if (!/^https?:\/\//i.test(baseUrl)) throw new Error('radicaleCalendarUrl fehlt oder ist ungültig.');

const operations = [];
for (const event of desired.values()) {
  const previous = state.hashByHref[event.href];
  const previousHash = typeof previous === 'string' ? previous : previous?.hash;
  if (previousHash !== event.hash) operations.push({ method: 'PUT', url: baseUrl + event.href, body: event.body, href: event.href, course: event.course });
}
for (const [href, previous] of Object.entries(state.hashByHref)) {
  const date = typeof previous === 'object' ? previous.date : null;
  const covered = date && feedMinDate && feedMaxDate && date >= feedMinDate && date <= feedMaxDate;
  if (!desired.has(href) && covered) operations.push({ method: 'DELETE', url: baseUrl + href, body: '', href, course: 'entfallen' });
}

// Der Sync-Status wird hier nur berechnet, nicht geschrieben. Geschrieben
// wird er im Knoten "Sync-Status festschreiben", also erst nachdem die
// HTTP-Knoten durch sind. Vorher festgeschrieben bedeutete: ein
// fehlgeschlagener PUT galt trotzdem als synchronisiert, previousHash war
// gleich event.hash, und der Termin wurde nie wieder angefasst -- er blieb
// dauerhaft veraltet, ohne dass irgendetwas davon berichtete.
const retained = Object.entries(state.hashByHref).filter(([, previous]) => {
  const date = typeof previous === 'object' ? previous.date : null;
  return !date || date < feedMinDate || date > feedMaxDate;
});
const nextState = {
  ...Object.fromEntries(retained),
  ...Object.fromEntries([...desired.values()].map(event => [event.href, { hash: event.hash, date: event.date }])),
};

const summary = {
  matched: matchedLessons,
  calendarBreaks: CALENDAR_BREAKS.length,
  managedTotal: desired.size,
  ignored,
  changes: operations.length,
  range: `${feedMinDate} bis ${feedMaxDate}`,
  warnings,
};
if (!operations.length) return [{ json: { dryRun: Boolean(cfg.dryRun), noop: true, summary } }];
return operations.map(operation => ({ json: { ...operation, dryRun: Boolean(cfg.dryRun), summary, nextState } }));

// Laeuft erst, wenn beide HTTP-Zweige durch sind. Schlaegt einer fehl, bricht
// n8n vorher ab, dieser Knoten laeuft nicht, und hashByHref bleibt unberuehrt
// -- der naechste Lauf sieht die Differenz erneut und versucht es wieder.
const items = $input.all();
const carrier = items.find((item) => item.json?.nextState);
if (!carrier) return items;

const state = $getWorkflowStaticData('global');
const previousState = state.hashByHref ?? {};

const unfoldIcs = (body) => String(body ?? '').replace(/\r\n[ \t]/g, '');
const unescapeIcs = (value) =>
  String(value ?? '')
    .replace(/\\n/g, ' ')
    .replace(/\\,/g, ',')
    .replace(/\\;/g, ';')
    .replace(/\\\\/g, '\\');
const parseSummary = (body) => {
  const match = /^SUMMARY:(.*)$/m.exec(unfoldIcs(body));
  return match ? unescapeIcs(match[1]) : null;
};
const parseStart = (body) => {
  const match = /DTSTART[^:]*:(\d{8})T(\d{4})/.exec(unfoldIcs(body));
  if (!match) return null;
  const [, ymd, hm] = match;
  return `${ymd.slice(6, 8)}.${ymd.slice(4, 6)}. ${hm.slice(0, 2)}:${hm.slice(2, 4)}`;
};

// DELETE requests carry an empty body -- the summary text only survives in
// the hash entry recorded the last time this href was written.
const changes = items
  .filter((item) => item.json?.method)
  .map((item) => {
    const { method, href, body } = item.json;
    if (method === 'PUT') {
      return { method, label: parseSummary(body) || href, when: parseStart(body) };
    }
    const prior = previousState[href];
    const priorDate = prior?.date ? `${prior.date.slice(8, 10)}.${prior.date.slice(5, 7)}.` : null;
    return { method, label: 'Termin entfällt', when: priorDate };
  })
  .sort((a, b) => (a.when ?? '').localeCompare(b.when ?? ''));

state.hashByHref = carrier.json.nextState;

return [
  {
    json: {
      recorded: Object.keys(carrier.json.nextState).length,
      operations: items.length,
      summary: carrier.json.summary ?? null,
      changes,
    },
  },
];
